mapper.select:
SELECT DISTINCT master_kpi_id
FROM kpi_template_items
WHERE template_id = #{templateId}

mapper.update:
UPDATE kpi_template_items
SET default_target_value = #{defaultTargetValue},
    default_weight = #{defaultWeight}
WHERE id = #{itemId}
  AND template_id = #{templateId}

mapper.delete:
DELETE FROM kpi_template_items
WHERE id = #{itemId}
  AND template_id = #{templateId}
